      sel.value=String(nxMonitor[key]);sel.addEventListener('change',function(){nxMonitor[key]=['opacity','scale'].includes(key)?Number(sel.value):sel.value;if(key==='position'){nxMonitor.x=null;nxMonitor.y=null;}nxMonitorSave();});
